import sys

MOD = 998244353
sys.setrecursionlimit(10000)

def solve():
    data = list(map(int, sys.stdin.buffer.read().split()))
    if not data:
        return
    n, m = data[0], data[1]
    parent = [x - 1 for x in data[2:]]

    indeg = [0] * n
    for p in parent:
        indeg[p] += 1
    queue = [i for i in range(n) if indeg[i] == 0]
    for v in queue:
        w = parent[v]
        indeg[w] -= 1
        if indeg[w] == 0:
            queue.append(w)

    on_cycle = [d != 0 for d in indeg]
    children = [[] for _ in range(n)]
    for v, p in enumerate(parent):
        if not (on_cycle[v] and on_cycle[p]):
            children[p].append(v)

    def tree_dp(v):
        result = [1] * (m + 1)
        for u in children[v]:
            child = tree_dp(u)
            prefix = 0
            for value in range(1, m + 1):
                prefix = (prefix + child[value]) % MOD
                result[value] = result[value] * prefix % MOD
        return result

    seen = [False] * n
    answer = 1
    for start in range(n):
        if on_cycle[start] and not seen[start]:
            cycle = []
            v = start
            while not seen[v]:
                seen[v] = True
                cycle.append(v)
                v = parent[v]

            ways = [1] * (m + 1)
            for root in cycle:
                dp = tree_dp(root)
                for value in range(1, m + 1):
                    ways[value] = ways[value] * dp[value] % MOD
            answer = answer * (sum(ways[1:]) % MOD) % MOD

    print(answer)

if __name__ == '__main__':
    solve()

