import sys
MOD=998244353

def factor(x):
    r = {}
    d = 2
    while d * d <= x:
        while x % d == 0:
            r[d] = r.get(d, 0) + 1
            x //= d
        d += 1
    if x > 1:
        r[x] = r.get(x, 0) + 1
    return r

def contribution(p, steps):
    height_limit = sum(steps)
    powers = [1] * (height_limit + 1)
    for h in range(1, height_limit + 1):
        powers[h] = powers[h - 1] * p % MOD

    hit = [0] * (height_limit + 1)
    free = [0] * (height_limit + 1)
    hit[0] = 1
    for h in range(1, height_limit + 1):
        free[h] = powers[h]

    for step in steps:
        new_hit = [0] * (height_limit + 1)
        new_free = [0] * (height_limit + 1)
        if step == 0:
            for h in range(height_limit + 1):
                mul = powers[h]
                new_hit[h] = hit[h] * mul % MOD
                new_free[h] = free[h] * mul % MOD
        else:
            for h in range(height_limit + 1):
                v = hit[h]
                if v:
                    x = h - step
                    if x >= 0:
                        new_hit[x] = (new_hit[x] + v * powers[x]) % MOD
                    x = h + step
                    if x <= height_limit:
                        new_hit[x] = (new_hit[x] + v * powers[x]) % MOD
                v = free[h]
                if v:
                    x = h - step
                    if x >= 0:
                        if x == 0:
                            new_hit[0] = (new_hit[0] + v) % MOD
                        else:
                            new_free[x] = (new_free[x] + v * powers[x]) % MOD
                    x = h + step
                    if x <= height_limit:
                        new_free[x] = (new_free[x] + v * powers[x]) % MOD
        hit, free = new_hit, new_free
    return sum(hit) % MOD

