import sys

MOD = 998244353

def main():
    data = list(map(int, sys.stdin.buffer.read().split()))
    if not data:
        return
    n = data[0]
    a = data[1:]
    mx = max(a)

    spf = list(range(mx + 1))
    for i in range(2, int(mx ** 0.5) + 1):
        if spf[i] == i:
            for j in range(i * i, mx + 1, i):
                if spf[j] == j:
                    spf[j] = i

    phi = list(range(mx + 1))
    if mx >= 1:
        phi[1] = 1
    for i in range(2, mx + 1):
        p = spf[i]
        q = i // p
        phi[i] = phi[q] * (p if q % p == 0 else p - 1)

    weights = [0] * (mx + 1)
    divisor_cache = {}
    power = 1
    answer = 0
    output = []

    for x in a:
        divisors = divisor_cache.get(x)
        if divisors is None:
            divisors = [1]
            y = x
            while y > 1:
                p = spf[y]
                exponent = 0
                while y % p == 0:
                    y //= p
                    exponent += 1
                old = divisors[:]
                multiple = 1
                for _ in range(exponent):
                    multiple *= p
                    divisors.extend(v * multiple for v in old)
            divisor_cache[x] = divisors

        added = 0
        for d in divisors:
            added = (added + phi[d] * weights[d]) % MOD

        answer = (2 * answer + added) % MOD
        output.append(str(answer))

        for d in divisors:
            weights[d] = (weights[d] + power) % MOD
        power = power * 2 % MOD

    sys.stdout.write('\n'.join(output))

if __name__ == "__main__":
    main()

