from heapq import heappush, heappop

class Solution:
    def maxSubarrays(self, n: int, conflictingPairs):
        by_right = [[] for _ in range(n + 1)]
        for index, (a, b) in enumerate(conflictingPairs):
            if a > b:
                a, b = b, a
            by_right[b].append((a, index))

        heap = []
        gains = [0] * len(conflictingPairs)
        baseline = 0

        for right in range(1, n + 1):
            for left, index in by_right[right]:
                heappush(heap, (-left, index))

            if not heap:
                baseline += right
                continue

            first = heappop(heap)
            maximum = -first[0]
            if heap:
                second = heappop(heap)
                second_value = -second[0]
                heappush(heap, second)
            else:
                second_value = 0
            heappush(heap, first)

            baseline += right - maximum
            if second_value < maximum:
                gains[first[1]] += maximum - second_value

        return baseline + max(gains)

