    def numberOfWays(self, n: int, x: int, y: int) -> int:
        MOD = 10**9 + 7
        limit = min(n, x)
        dp = [0] * (limit + 1)
        dp[0] = 1
        for _ in range(n):
            ndp = [0] * (limit + 1)
            for used, ways in enumerate(dp):
                if ways:
                    ndp[used] = (ndp[used] + ways * used) % MOD
                    if used < x:
                        ndp[used + 1] = (ndp[used + 1] + ways * (x - used) * y) % MOD
            dp = ndp
        return sum(dp) % MOD

