class Solution:
    def countKReducibleNumbers(self, s: str, k: int) -> int:
        MOD = 10**9 + 7
        n = len(s)

        comb = [[0] * (n + 1) for _ in range(n + 1)]
        for i in range(n + 1):
            comb[i][0] = comb[i][i] = 1
            for j in range(1, i):
                comb[i][j] = (comb[i - 1][j - 1] + comb[i - 1][j]) % MOD

        good = [False] * (n + 1)
        for t in range(1, n + 1):
            v = t
            steps = 0
            while v != 1:
                v = v.bit_count()
                steps += 1
            good[t] = steps <= k - 1

        answer = 0
        ones_so_far = 0
        for i, ch in enumerate(s):
            if ch == '1':
                remaining = n - i - 1
                for t in range(1, n + 1):
                    required = t - ones_so_far
                    if good[t] and 0 <= required <= remaining:
                        answer = (answer + comb[remaining][required]) % MOD
                ones_so_far += 1

        return answer

