        lo = max(0, h - d[0])
        hi = min(u[0], h)
        if lo > hi:
            return False
        for i in range(1, n):
            nlo = max(0, h - d[i], lo - x)
            nhi = min(u[i], h, hi + x)
            if nlo > nhi:
                return False
            lo, hi = nlo, nhi
        return True

    left = 0
    right = min(a + b for a, b in zip(u, d))
    while left < right:
        mid = (left + right + 1) // 2
        if feasible(mid):
            left = mid
        else:
            right = mid - 1

    print(sum(u) + sum(d) - n * left)

