from typing import List

class Solution:
    def permute(self, n: int, k: int) -> List[int]:
        fact = [1] * (n + 1)
        for i in range(1, n + 1):
            fact[i] = fact[i - 1] * i

        unused = list(range(1, n + 1))
        odd = (n + 1) // 2
        even = n // 2
        result = []
        required = None

        def completions(o, e, next_parity):
            remaining = o + e
            high = (remaining + 1) // 2
            low = remaining // 2
            if next_parity == 1:
                valid = (o == high and e == low)
            else:
                valid = (e == high and o == low)
            return fact[o] * fact[e] if valid else 0

        for _ in range(n):
            for value in unused:
                parity = value & 1
                if required is not None and parity != required:
                    continue

                new_odd = odd - (parity == 1)
                new_even = even - (parity == 0)
                count = completions(new_odd, new_even, 1 - parity)

                if k > count:
                    k -= count
                elif count:
                    result.append(value)
                    unused.remove(value)
                    odd, even = new_odd, new_even
                    required = 1 - parity
                    break
            else:
                return []

        return result

