class Solution:
    def largestPalindrome(self, n: int, k: int) -> str:
        full = (1 << k) - 1
        m = (n + 1) // 2

        powers = [1] * n
        for i in range(1, n):
            powers[i] = powers[i - 1] * 10 % k

        weights = [
            (powers[j] + powers[n - 1 - j]) % k
            if j < n // 2 else powers[j] % k
            for j in range(m)
        ]

        suffix = [0] * (m + 1)
        suffix[m] = 1  # only residue 0 is achievable by an empty suffix
        for i in range(m - 1, -1, -1):
            mask = 0
            for digit in range(10):
                shift = digit * weights[i] % k
                if shift == 0:
                    mask |= suffix[i + 1]
                else:
                    nxt = suffix[i + 1]
                    mask |= ((nxt << shift) | (nxt >> (k - shift))) & full
            suffix[i] = mask

        left = []
        needed = 0
        for i in range(m):
            minimum = 1 if i == 0 else 0
            for digit in range(9, minimum - 1, -1):
                remainder = (needed - digit * weights[i]) % k
                if (suffix[i + 1] >> remainder) & 1:
                    left.append(str(digit))
                    needed = remainder
                    break

        left = ''.join(left)
        return left + left[:-1 if n % 2 else None][::-1]

