from typing import List

class Solution:
    def countNonDecreasingSubarrays(self, nums: List[int], k: int) -> int:
        n = len(nums)
        a = nums
        pref = [0] * (n + 1)
        for i, x in enumerate(a):
            pref[i + 1] = pref[i] + x

        nxt = [n] * n
        stack = []
        for i in range(n - 1, -1, -1):
            while stack and a[stack[-1]] <= a[i]:
                stack.pop()
            nxt[i] = stack[-1] if stack else n
            stack.append(i)

        levels = n.bit_length()
        up = [nxt] + [[n] * n for _ in range(levels - 1)]
        sums = [[0] * n for _ in range(levels)]
        for i in range(n):
            j = nxt[i]
            sums[0][i] = a[i] * (j - i) - (pref[j] - pref[i])

        for p in range(1, levels):
            prev = up[p - 1]
            cur_up = up[p]
            prev_sum = sums[p - 1]
            cur_sum = sums[p]
            for i in range(n):
                j = prev[i]
                cur_up[i] = n if j == n else prev[j]
                cur_sum[i] = prev_sum[i] + (0 if j == n else prev_sum[j])

        def cost(left, right_exclusive):
            node = left
            result = 0
            for p in range(levels - 1, -1, -1):
                if node == n:
                    break
                j = up[p][node]
                if j <= right_exclusive:
                    result += sums[p][node]
                    if result > k:
                        return k + 1
                    node = j
            if node < right_exclusive:
                result += (a[node] * (right_exclusive - node)
                           - (pref[right_exclusive] - pref[node]))
            return result

        answer = 0
        for right in range(n):
            lo, hi = 0, right
            while lo < hi:
                mid = (lo + hi) // 2
                if cost(mid, right + 1) <= k:
                    hi = mid
                else:
                    lo = mid + 1
            answer += right - lo + 1
        return answer

