        a, b = x
        c, d = y
        if a == 1:
            return 0 if c == 1 else -1
        if c == 1:
            return 1
        left = b * (c - 1)
        right = d * (a - 1)
        if left > right:
            return -1
        if left < right:
            return 1
        return 0

