import sys
import heapq

def main():
    data = list(map(int, sys.stdin.buffer.read().split()))
    if not data:
        return
    n = data[0]
    g = [[] for _ in range(n)]
    j = 1
    for _ in range(n - 1):
        u, v, w = data[j] - 1, data[j + 1] - 1, data[j + 2]
        j += 3
        g[u].append((v, w))
        g[v].append((u, w))

    parent = [-1] * n
    parent_weight = [0] * n
    order = [0]
    for x in order:
        for y, w in g[x]:
            if y != parent[x]:
                parent[y] = x
                parent_weight[y] = w
                order.append(y)

    heaps = [None] * n
    for x in reversed(order):
        h = None
        for y, _ in g[x]:
            if parent[y] == x and (h is None or len(heaps[y]) > len(h)):
                h = heaps[y]
        if h is None:
            h = [0]
        for y, _ in g[x]:
            if parent[y] == x and heaps[y] is not h:
                for value in heaps[y]:
                    heapq.heappush(h, value)
        if x != 0:
            heapq.heapreplace(h, h[0] - parent_weight[x])
        heaps[x] = h

    gains = sorted((-x for x in heaps[0]), reverse=True)
    answer = []
    total = 0
    for k in range(1, n + 1):
        if k <= len(gains):
            total += gains[k - 1]
        answer.append(str(2 * total))
    sys.stdout.write('\n'.join(answer))

if __name__ == '__main__':
    main()

