import sys, heapq

def scores(a):
    n = len(a)
    out = [0] * (n + 1)
    lo, hi = [], []
    sl = su = 0
    for j, x in enumerate(a, 1):
        if not lo or x <= -lo[0]:
            heapq.heappush(lo, -x); sl += x
        else:
            heapq.heappush(hi, x); su += x
        while len(lo) > (j + 1) // 2:
            y = -heapq.heappop(lo); sl -= y
            heapq.heappush(hi, y); su += y
        while len(lo) < (j + 1) // 2:
            y = heapq.heappop(hi); su -= y
            heapq.heappush(lo, -y); sl += y
        while hi and -lo[0] > hi[0]:
            x = -heapq.heappop(lo); y = heapq.heappop(hi)
            sl += y - x; su += x - y
            heapq.heappush(lo, -y); heapq.heappush(hi, x)
        if j % 2 == 0:
            out[j] = su - sl
    return out

def main():
    data = list(map(int, sys.stdin.buffer.read().split()))
    n = data[0]
    a = data[1:]
    pref = scores(a)
    if n % 2 == 0:
