MOD = 998244353

def count_ways(H, W, grid):
    parent = list(range(H))
    parity = [0] * H

    def find(a):
        if parent[a] != a:
            p = parent[a]
            parent[a] = find(p)
            parity[a] ^= parity[p]
        return parent[a]

    def unite(a, b, v):
        ra = find(a)
        va = parity[a]
        rb = find(b)
        vb = parity[b]
        if ra == rb:
            return (va ^ vb) == v
        parent[ra] = rb
        parity[ra] = va ^ vb ^ v
        return True

    # q[i][j] is the parity of A tiles before column j in row i.
    q = [[0] * W for _ in range(H)]
    for i in range(H):
        z = 0
        row = grid[i]
        for j, c in enumerate(row):
            q[i][j] = z
            if c == 'A':
                z ^= 1
        if z:
            return 0

    free_columns = 0
    for j in range(W):
        row_parity = 0
        first = None
        for i in range(H):
            if grid[i][j] == 'B':
                v = q[i][j] ^ row_parity
                if first is None:
                    first = (i, v)
                elif not unite(first[0], i, first[1] ^ v):
                    return 0
            else:
                row_parity ^= 1
        if row_parity:
            return 0
        if first is None:
            free_columns += 1

    components = len({find(i) for i in range(H)})
    return pow(2, components + free_columns, MOD)

