from bisect import bisect_left

class Solution:
    def shortestMatchingSubstring(self, s: str, p: str) -> int:
        A, B, C = p.split('*')
        n = len(s)
        INF = 10**18

        def occurrences(t):
            if not t:
                return list(range(n + 1))
            pi = [0] * len(t)
            for i in range(1, len(t)):
                j = pi[i - 1]
                while j and t[i] != t[j]:
                    j = pi[j - 1]
                if t[i] == t[j]:
                    j += 1
                pi[i] = j
            result = []
            j = 0
            for i, ch in enumerate(s):
                while j and ch != t[j]:
                    j = pi[j - 1]
                if ch == t[j]:
                    j += 1
                if j == len(t):
                    result.append(i - len(t) + 1)
                    j = pi[j - 1]
            return result

        starts_a = occurrences(A)
        starts_b = occurrences(B)
        starts_c = occurrences(C)

        ends = []
        for b in starts_b:
            k = bisect_left(starts_c, b + len(B))
            if k < len(starts_c):
                ends.append(starts_c[k] + len(C))
            else:
                ends.append(INF)

        suffix_min = [INF] * len(ends)
        cur = INF
        for i in range(len(ends) - 1, -1, -1):
            cur = min(cur, ends[i])
            suffix_min[i] = cur

        answer = INF
        for a in starts_a:
            i = bisect_left(starts_b, a + len(A))
            if i < len(starts_b) and suffix_min[i] < INF:
                answer = min(answer, suffix_min[i] - a)

        return -1 if answer == INF else answer

