    for _ in range(m):
        x, y, z = data[p] - 1, data[p + 1] - 1, data[p + 2]
        p += 3
        adj[x].append((y, z))
        adj[y].append((x, z))
    a = [-1] * n
    for s in range(n):
        if a[s] >= 0:
            continue
        a[s] = 0
        stack = [s]
        comp = []
        while stack:
            u = stack.pop()
            comp.append(u)
            for v, z in adj[u]:
                w = a[u] ^ z
                if a[v] < 0:
                    a[v] = w
                    stack.append(v)
                elif a[v] != w:
                    print(-1)
                    return
        shift = 0
        for bit in range(30):
            if sum((a[u] >> bit) & 1 for u in comp) * 2 > len(comp):
                shift |= 1 << bit
        for u in comp:
