import sys
import itertools

def main():
    data = list(map(int, sys.stdin.buffer.read().split()))
    if not data:
        return
    n, k = data[0], data[1]
    a = data[2:]

    total = 0
    for v in a:
        total ^= v

    r = min(k, n - k)
    if r == 0:
        print(total)
        return

    ans = 0
    if k <= n - k:
        for chosen in itertools.combinations(a, k):
            value = 0
            for v in chosen:
                value ^= v
            if value > ans:
                ans = value
    else:
        # XOR of a chosen K-set equals total XOR the XOR of its complement.
        for excluded in itertools.combinations(a, r):
            value = total
            for v in excluded:
                value ^= v
            if value > ans:
                ans = value

    print(ans)

if __name__ == "__main__":
    main()

