    def findAnswer(self, parent: List[int], s: str) -> List[bool]:
        n = len(parent)
        children = [[] for _ in range(n)]
        for i in range(1, n):
            children[parent[i]].append(i)

        order = []
        stack = [(0, False)]
        while stack:
            x, done = stack.pop()
            if done:
                order.append(x)
            else:
                stack.append((x, True))
                for y in reversed(children[x]):
                    stack.append((y, False))

        transformed = [0] * (2 * n + 1)
        for i, x in enumerate(order):
            transformed[2 * i + 1] = ord(s[x]) - 96

        radius = [0] * len(transformed)
        center = right = 0
        for i in range(len(transformed)):
            mirror = 2 * center - i
            if i < right:
                radius[i] = min(right - i, radius[mirror])
            while (i - 1 - radius[i] >= 0 and
                   i + 1 + radius[i] < len(transformed) and
                   transformed[i - 1 - radius[i]] == transformed[i + 1 + radius[i]]):
                radius[i] += 1
            if i + radius[i] > right:
                center, right = i, i + radius[i]

        position = [0] * n
        for i, x in enumerate(order):
            position[x] = i
        size = [1] * n
        for x in reversed(order):
            if parent[x] != -1:
                size[parent[x]] += size[x]

        answer = []
        for x in range(n):
            r = position[x]
            l = r - size[x] + 1
            answer.append(radius[l + r + 1] >= size[x])
        return answer

