import sys
MOD=998244353

def solve():
    n = int(sys.stdin.readline())
    s = sys.stdin.readline().strip()
    dp = [0] * (n + 2)
    dp[0] = 1
    d = 0
    for k, c in enumerate(s):
        nd = [0] * (n + 2)
        if c == 'B':
            for a in range(n + 1):
                v = dp[a]
                if v:
                    q = a - d
                    if q > 0:
                        nd[a] = (nd[a] + v * q) % MOD
                    nd[a + 1] = (nd[a + 1] + v) % MOD
            d += 1
        else:
            for a in range(n + 1):
                v = dp[a]
                if v:
                    nd[a] = (nd[a] + v) % MOD
                    if a:
                        nd[a - 1] = (nd[a - 1] + v * a) % MOD
            d -= 1
        if k < len(s) - 1:
            nd[0] = 0
        dp = nd
    print(dp[0] % MOD)

solve()

