from typing import List

class Solution:
    def maxEnergyBoost(self, energyDrinkA: List[int], energyDrinkB: List[int]) -> int:
        n = len(energyDrinkA)
        if n == 1:
            return max(energyDrinkA[0], energyDrinkB[0])

        prev_a = energyDrinkA[0]
        prev_b = energyDrinkB[0]
        two_a, two_b = prev_a, prev_b
        cur_a = prev_a + energyDrinkA[1]
        cur_b = prev_b + energyDrinkB[1]

