import heapq

class Solution:
    def minOperations(self, n: int, m: int) -> int:
        if n == m:
            return -1 if self._prime(n) else n
        if self._prime(n) or self._prime(m):
            return -1

        width = len(str(n))
        limit = 10 ** width
        prime = [True] * limit
        prime[0] = prime[1] = False
        for i in range(2, int(limit ** 0.5) + 1):
            if prime[i]:
                prime[i * i:limit:i] = [False] * (((limit - 1 - i * i) // i) + 1)

        powers = [10 ** i for i in range(width)]
        inf = 10 ** 18
        dist = [inf] * limit
        dist[n] = n
        heap = [(n, n)]

        while heap:
            cost, value = heapq.heappop(heap)
            if cost != dist[value]:
                continue
            if value == m:
                return cost

            for power in powers:
                digit = (value // power) % 10
                if digit > 0:
                    nxt = value - power
                    if not prime[nxt] and cost + nxt < dist[nxt]:
                        dist[nxt] = cost + nxt
                        heapq.heappush(heap, (dist[nxt], nxt))
                if digit < 9:
                    nxt = value + power
                    if not prime[nxt] and cost + nxt < dist[nxt]:
                        dist[nxt] = cost + nxt
                        heapq.heappush(heap, (dist[nxt], nxt))
        return -1

    @staticmethod
    def _prime(x: int) -> bool:
        if x < 2:
            return False
        d = 2
        while d * d <= x:
            if x % d == 0:
                return False
            d += 1
        return True

