class Solution:
    def beautifulSplits(self, nums: List[int]) -> int:
        n = len(nums)
        z = [0] * n
        left = right = 0
        for i in range(1, n):
            if i <= right:
                z[i] = min(right - i + 1, z[i - left])
            while i + z[i] < n and nums[z[i]] == nums[i + z[i]]:
                z[i] += 1
            if i + z[i] - 1 > right:
                left, right = i, i + z[i] - 1

        answer = 0
        next_row = [0] * (n + 1)
        for i in range(n - 2, 0, -1):
            first_works = z[i] >= i
            if first_works:
                answer += n - i - 1
            row = [0] * (n + 1)
            for j in range(n - 1, i, -1):
                if nums[i] == nums[j]:
                    row[j] = 1 + next_row[j + 1]
                    if not first_works and row[j] >= j - i:
                        answer += 1
            next_row = row
        return answer

