class Solution:
    def maxRemovals(self, source: str, pattern: str, targetIndices: List[int]) -> int:
        marked = [False] * len(source)
        for i in targetIndices:
            marked[i] = True

        inf = 10**9
        # dp[j] is the minimum number of target characters used by a
        # matching subsequence for pattern[:j+1] seen so far.
        dp = [inf] * len(pattern)
        for i, ch in enumerate(source):
            cost = 1 if marked[i] else 0
            for j in range(len(pattern) - 1, -1, -1):
                if ch == pattern[j]:
                    if j == 0:
                        if cost < dp[0]:
                            dp[0] = cost
                    elif dp[j - 1] < inf:
                        candidate = dp[j - 1] + cost
                        if candidate < dp[j]:
                            dp[j] = candidate

        return len(targetIndices) - dp[-1]

