from typing import List

class Solution:
    def minMaxWeight(self, n: int, edges: List[List[int]], threshold: int) -> int:
        if threshold < 1:
            return -1

        weights = sorted({w for _, _, w in edges})
        reverse = [[] for _ in range(n)]
        for a, b, w in edges:
            reverse[b].append((a, w))

        def feasible(limit: int) -> bool:
            seen = [False] * n
            seen[0] = True
            stack = [0]
            count = 1
            while stack:
                v = stack.pop()
                for u, w in reverse[v]:
                    if w <= limit and not seen[u]:
                        seen[u] = True
                        count += 1
                        stack.append(u)
            return count == n

