class Solution:
    def countOfSubstrings(self, word: str, k: int) -> int:
        vowels = set('aeiou')
        def atmost(K):
            if K < 0: return 0
            left = cons = ans = 0
            last = {c: -1 for c in vowels}
            for right, ch in enumerate(word):
                if ch in vowels: last[ch] = right
                else: cons += 1
                while cons > K:
                    if word[left] not in vowels: cons -= 1
                    left += 1
                m = min(last.values())
                if m >= left: ans += m-left+1
